(* [comment removed for export] *)
Inductive arm : Type := ArmA | ArmB | ArmC.
Definition gpc (x : arm) : Z := match x with ArmA => 0x3aaa4 | ArmB => 0x3ab8c | ArmC => 0x3ac78 end.
Definition tpc (x : arm) : Z := match x with ArmA => 0x3ab04 | ArmB => 0x3abec | ArmC => 0x3acd8 end.
Definition upc (x : arm) : Z := match x with ArmA => 0x3ab50 | ArmB => 0x3ac38 | ArmC => 0x3ad20 end.
Definition jpc (x : arm) : Z := match x with ArmA => 0x3ab7c | ArmB => 0x3ac64 | ArmC => 0x3ad4c end.
Definition sreg (x : arm) : nat := match x with ArmA => 18 | ArmB => 19 | ArmC => 22 end.
Definition creg (x : arm) : nat := match x with ArmA => 19 | ArmB => 20 | ArmC => 23 end.


Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Let KL := PMKS.klayout_S L LY.
Let SF := PMKS.sfoot_S L LY.
Hypothesis OPN : PQAS.opnew_spec_n RSEGS AD L HI PQAS.NREQ.
Hypothesis OPD : PMS.opdel_spec L HI.
(* [comment removed for export] *)
Hypothesis VBE : NECS.v_begin_obj_spec RSEGS AD AQ AE L HI NESK.PME.
Abbreviation ae_at := (NEM.ae_at RSEGS AD AE L PMSP.T3 PMSP.T4 (qa_vp_adaptor AQ)).
Abbreviation enc_at := (NEM.enc_at RSEGS AE L PMSP.T3 PMSP.T4).
Abbreviation sink_at := (NESK.sink_at RSEGS L PMSP.T3 PMSP.T4 NESK.PME).

