Definition armregs (x : arm) (R : bvmap 5 word) (kb1 : PM.vstr) (g1 : Z) (kbb1 : list Z) : Prop :=
  match x with ArmA => tnew = 1 | ArmB => tnew = 1 /\ getr R (reg 18) = Z_to_bv 64 (oa + 48)
  | ArmC => tnew = 0 /\ kb1 = kb /\ g1 = kbg /\ kbb1 = kbb /\ getr R (reg 21) = getr R0 (reg 11) /\ getr R (reg 18) = Z_to_bv 64 oec end.
Lemma armregs_xfer x R R' kb1 g1 kbb1 : armregs x R kb1 g1 kbb1 -> getr R' (reg 18) = getr R (reg 18) -> getr R' (reg 21) = getr R (reg 21) -> armregs x R' kb1 g1 kbb1.
Proof.
