  getr R (reg 1) = Z_to_bv 64 (jpc x) -> getr R (reg 10) = Z_to_bv 64 b -> getr R (reg 2) = Z_to_bv 64 (S - 112) -> getr R (reg 8) = Z_to_bv 64 oa ->
  getr R (reg (sreg x)) = Z_to_bv 64 (B0 + 24 * (n + 1)) -> kept0 R ->
  saves M -> cme M -> world M -> adaptor_at M oa ov (stQ B0 (k + 1) kb1 g1) -> PQM.ks_ok PQM.SMB kb1 g1 -> PM.vs_size kb1 <= PM.vs_size kb + 1 ->
  xinv M kb1 kbb1 ->
  PMSP.credit_keep cr0 cr (PQM.pot_adaptor L ast) (PQM.pot_adaptor L (stQ B0 (k + 1) kb1 g1)) -> model_but_vm model0 model ->
  hi_heap HI ((B0, 24 * 2 ^ (k + 1)) :: PQM.aown (stX lv b k kb1 g1) ++ LBXe) cr M (m_vmmaps model) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x63dc4 M model) K.
