(* [comment removed for export] *)
Lemma ALST (x : arm) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (kb1 : PM.vstr) (g1 : Z) (kbb1 : list Z) (cr : credit) :
  n = 2 ^ k -> k <= 10 -> armregs x R kb1 g1 kbb1 ->
  getr R (reg 1) = Z_to_bv 64 (tpc x) -> getr R (reg 2) = Z_to_bv 64 (S - 112) -> getr R (reg 8) = Z_to_bv 64 oa -> getr R (reg 9) = Z_to_bv 64 (oa + 72) ->
  getr R (reg 11) = Z_to_bv 64 (2 ^ (k + 1)) -> getr R (reg (sreg x)) = Z_to_bv 64 (24 * 2 ^ k) -> kept0 R ->
  saves M -> cme M -> world M -> adaptor_at M oa ov (stX lv b k kb1 g1) -> PQM.ks_ok PQM.SMB kb1 g1 -> PM.vs_size kb1 <= PM.vs_size kb + 1 ->
  xinv M kb1 kbb1 ->
  PMSP.credit_keep cr0 cr (PQM.pot_adaptor L ast) (PQM.pot_adaptor L (stX lv b k kb1 g1)) -> model_but_vm model0 model ->
  hi_heap HI (PQM.aown (stX lv b k kb1 g1) ++ LBXe) cr M (m_vmmaps model) ->
